/**
 * Typed wrapper around the Emscripten output generated by
 * `scripts/build-cephonemizer.js`.
 *
 * Keep this file small and hand-maintained. The large sibling file
 * `cephonemizer-runtime.js` is generated from the vendored C++ source and
 * should not be edited manually.
 */
export interface CEPhonemizerFS {
  /** Create a directory inside Emscripten MEMFS. */
  mkdir(path: string): void;
  /** Write dictionary/rule text into Emscripten MEMFS. */
  writeFile(path: string, data: string): void;
}

export interface CEPhonemizerModule {
  FS: CEPhonemizerFS;
  /** Convert a null-terminated UTF-8 string pointer from the Emscripten heap. */
  UTF8ToString(ptr: number): string;
  /** Create a JavaScript callable wrapper for an exported C function. */
  cwrap(
    ident: string,
    returnType: 'number' | null,
    argTypes: Array<'number' | 'string'>,
  ): unknown;
}

type CEPhonemizerModuleFactory = () => Promise<CEPhonemizerModule>;

declare const require: (path: string) => unknown;

const createCEPhonemizerModule =
  require('./cephonemizer-runtime') as CEPhonemizerModuleFactory;

export default createCEPhonemizerModule;
